  "local init": {
    "usage": "pbc local init [<version>] [--dir <d>] [--force]",
    "summary": "Download a PocketBase binary and scaffold a local project.",
    "details": "Downloads the binary for this OS and CPU, then creates pb_hooks/,\npb_migrations/, a README.md, .gitignore entries (which exclude the\nbinary and pb_data/), and a pocketbaseVersion pin in pbc.json. Existing\nfiles are never overwritten. Omit <version> for the latest release;\n--force re-downloads the binary only.\n\nStart the instance afterwards with `./pocketbase serve`.",
    "args": [
      {
        "name": "version",
        "required": false,
        "description": "Release to install, e.g. 0.39.9. Defaults to latest."
      }
    ],
    "flags": [
      {
        "name": "dir",
        "type": "string",
        "required": false,
        "description": "Directory to install into. Defaults to the current directory."
      },
      {
        "name": "force",
        "type": "boolean",
        "required": false,
        "description": "Re-download the binary even if it is already present."
      },
      {
        "name": "os",
        "type": "string",
        "required": false,
        "choices": [
          "darwin",
          "linux",
          "windows"
        ],
        "description": "Override OS detection: darwin, linux, or windows."
      },
      {
        "name": "arch",
        "type": "string",
        "required": false,
        "choices": [
          "amd64",
          "arm64",
          "armv7",
          "ppc64le",
          "s390x"
        ],
        "description": "Override CPU detection: amd64, arm64, armv7, ppc64le, or s390x."
      }
    ]
  },
