  "self upgrade": {
    "usage": "pbc self upgrade [<version>] [--check] [--force] [--json]",
    "summary": "Update pbc itself to the latest release.",
    "details": "Downloads the release archive for this OS and CPU, verifies its\nSHA-256 against the release's checksums.txt, and replaces the running\nbinary. Nothing is changed unless the checksum matches.\n\nPass a <version> to install a specific release, including an older one\nto roll back. --check reports what is available without installing;\n--force reinstalls the version you already have.\n\nOnly a standalone binary (the `curl | sh` installer, or a release\narchive) can be replaced in place. An npm install must be updated with\nnpm, and a from-source install by updating its clone; in both cases\n`pbc self upgrade` prints the exact command and exits non-zero.\n\npbc also looks for a newer release once a day on its own and mentions\none on stderr after a command finishes. Set PBC_NO_UPDATE_CHECK to turn\nthat off; it is already skipped under --json, CI, and redirected\noutput.\n\nTo change your plan, see `pbc plan` instead.",
    "args": [
      {
        "name": "version",
        "required": false,
        "description": "Release to install, e.g. 0.2.4. Defaults to the latest."
      }
    ],
    "flags": [
      {
        "name": "check",
        "type": "boolean",
        "required": false,
        "description": "Report the available version without installing it"
      },
      {
        "name": "force",
        "type": "boolean",
        "required": false,
        "description": "Reinstall even when already on the target version"
      }
    ]
  },
